# Let me analyze holes/enclosed regions in the grid
# Background is 0, foreground is 1
# I need to find regions of 0s that are completely surrounded by 1s

def find_holes(grid):
    """Find holes (0 cells surrounded by 1s) using flood fill from edges"""
    rows, cols = len(grid), len(grid[0])

    # Mark all 0s reaching from the edge as "outside"
    outside = set()
    from collections import deque

    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r, c) not in outside:
                # Check if this is on the edge
                if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:
                    outside.add((r, c))
                    queue.append((r, c))

    # BFS from edge zeros
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0 and (nr, nc) not in outside:
                    outside.add((nr, nc))
                    queue.append((nr, nc))

    # All 0s not in outside are holes
    holes = set((r, c) for r in range(rows) for c in range(cols) 
                if grid[r][c] == 0 and (r, c) not in outside)
    return holes, outside

holes, outside = find_holes(grid)
print(f"Number of hole cells: {len(holes)}")
print(f"Sample holes: {sorted(list(holes))[:20]}")

